function renderBuilder() {
  let qListHtml = "";
  if (customSurvey.axes[editorAxis].qs.length === 0) {
    qListHtml = `<div style="text-align:center; color:var(--muted); font-size:0.9rem; font-weight:600; padding:20px 0;">لم تقم بإضافة أي أسئلة بعد.</div>`;
  } else {
    qListHtml = customSurvey.axes[editorAxis].qs.map((q, i) => `
      <div class="q-item">
        <div class="q-item-num">${i + 1}.</div>
        <div class="q-item-text">${escapeHtml(q.text)}</div>
        <button class="btn-del" onclick="deleteQuestion(${i})">حذف</button>
      </div>
    `).join('');
  }

  stage.innerHTML = `
    <section class="screen active">
      <div class="builder-container">
        <div class="builder-card">
          <div class="builder-title">إعداد استبيان مخصص</div>
          <label class="field"><span>عنوان الاستبيان</span><input type="text" id="bTitle" value="${escapeHtml(customSurvey.title)}"></label>
          <label class="field"><span>اسم المعلمة / المقيّم</span><input type="text" id="bTeacher" value="${escapeHtml(customSurvey.teacher)}"></label>
          <label class="field"><span>الموضوع / الدرس</span><input type="text" id="bLesson" value="${escapeHtml(customSurvey.lesson)}"></label>
          
          <div style="margin-top: 30px; margin-bottom: 10px; font-weight: 800; color: var(--primary);">الأسئلة</div>
          <div class="add-q-row">
            <input type="text" id="newQText" placeholder="اكتب السؤال هنا..." onkeypress="if(event.key==='Enter') addQuestion()">
            <button class="btn-add" onclick="addQuestion()">+ إضافة</button>
          </div>
          <div class="q-list" id="builderList">${qListHtml}</div>

          <div class="builder-actions">
            <button class="btn-start" onclick="startCustomSurvey()" ${customSurvey.axes[editorAxis].qs.length === 0 ? 'disabled' : ''}>بدء الاستبيان الآن</button>
          </div>
        </div>
      </div>
    </section>
  `;

  document.getElementById('bTitle').addEventListener('input', (e) => customSurvey.title = e.target.value);
  document.getElementById('bTeacher').addEventListener('input', (e) => customSurvey.teacher = e.target.value);
  document.getElementById('bLesson').addEventListener('input', (e) => customSurvey.lesson = e.target.value);
}

function addQuestion() {
  const input = document.getElementById('newQText');
  const text = input.value.trim();
  if (!text) return;
  customSurvey.axes[editorAxis].qs.push(S3(text));
  input.value = "";
  renderBuilder();
}

function deleteQuestion(index) {
  customSurvey.axes[editorAxis].qs.splice(index, 1);
  renderBuilder();
}

/* =====================================================================
   4) محرك الاستبيان
   ===================================================================== */
function startSurvey(type) {
  activeSurveyKind = type;
  if (type === 'applied') activeSurvey = SURVEY_APPLIED;
  else if (type === 'workshop') activeSurvey = SURVEY_WORKSHOP;
  initSurveyEngine();
}

function startCustomSurvey() {
  if (customSurvey.axes[0].qs.length === 0) return;
  activeSurveyKind = 'custom';
  activeSurvey = customSurvey;
  initSurveyEngine();
}

function initSurveyEngine() {
  currentAppState = 'survey';
  navBar.style.display = "flex";
  progressContainer.style.visibility = "visible";
  btnReset.style.display = "block";

  ALL_Q = [];
  let qCounter = 0;
  activeSurvey.axes.forEach(ax => {
    ax.qs.forEach(q => {
      qCounter++;
      q.id = "q" + qCounter;
      q.num = qCounter;
      q.axisName = ax.name;
      ALL_Q.push(q);
    });
  });
  TOTAL_Q = ALL_Q.length;
  state = { answers: {}, notes: "", reviewerName: "" };
  buildSurveyUI();
  goTo(0);
}

function buildSurveyUI() {
  let html = "";

  // الغلاف
  html += `
    <section class="screen" data-idx="0">
      <div class="question-container">
        <div class="q-card" style="text-align: center; padding: 40px 30px;">
          <div class="survey-cover-logos"><img src="${SCHOOL_LOGO || 'data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22/%3E'}" alt="شعار المدرسة" ${SCHOOL_LOGO?'':'style="visibility:hidden"'}><div><b>${escapeHtml(SCHOOL_NAME)}</b><small>استبيانات مدار</small></div><img src="${VISION_2030_LOGO}" alt="رؤية 2030"></div>
          <h1 style="font-size: 1.8rem; font-weight: 900; color: var(--ink); margin-bottom: 10px;">${escapeHtml(activeSurvey.title)}</h1>
          <p style="font-size: 1rem; color: var(--muted); font-weight: 600; margin-bottom: 30px;">مشاركتك تساعد على تطوير الأداء</p>
          <div style="display: grid; gap: 12px; text-align: right; background: var(--bg); padding: 20px; border-radius: 14px; margin-bottom: 30px;">
            <div><span style="font-size: 0.8rem; color: var(--muted); font-weight: 700;">المعلمة</span><br><b style="font-size: 1rem; color: var(--ink);">${escapeHtml(activeSurvey.teacher)}</b></div>
            <div><span style="font-size: 0.8rem; color: var(--muted); font-weight: 700;">الموضوع</span><br><b style="font-size: 1rem; color: var(--ink);">${escapeHtml(activeSurvey.lesson)}</b></div>
          </div>
          <button class="nav-btn btn-next" style="width: 100%; justify-content: center; padding: 16px; font-size: 1.1rem;" onclick="goTo(1)">ابدأ التقييم</button>
        </div>
      </div>
    </section>
  `;

  // الأسئلة
  ALL_Q.forEach((q, i) => {
    const qIdx = i + 1;
    const segments = q.options.map((opt, optIdx) => `<div class="custom-segment" data-qid="${q.id}" data-idx="${optIdx}">${optIdx + 1}</div>`).join('');
    const labels = q.options.map((opt, optIdx) => `
      <div class="custom-label" data-qid="${q.id}" data-idx="${optIdx}">
        <div class="custom-tick"></div><div class="custom-text">${escapeHtml(opt)}</div>
      </div>`).join('');

    html += `
      <section class="screen" data-idx="${qIdx}">
        <div class="question-container">
          <div class="q-card" id="card-${q.id}">
            <div class="q-axis-badge">${escapeHtml(q.axisName)}</div>
            <div class="q-header">
              <div class="q-num">${q.num}</div>
              <div class="q-text">${escapeHtml(q.text)}</div>
            </div>
            <div class="custom-bar-wrapper">
              <div class="custom-bar">${segments}</div>
              <div class="custom-labels">${labels}</div>
            </div>
          </div>
        </div>
      </section>
    `;
  });

  // الملاحظات
  const notesIdx = TOTAL_Q + 1;
  html += `
    <section class="screen" data-idx="${notesIdx}">
      <div class="question-container">
        <div class="q-card">
          <div class="q-header">
            <div class="q-num" style="background: var(--ink2);">${TOTAL_Q + 1}</div>
            <div class="q-text">ملاحظات إضافية (اختياري)</div>
          </div>
          <label class="field"><span>اسم المقيمة من حسابك</span><input type="text" id="reviewerName" readonly autocomplete="name" value="${escapeHtml(state.reviewerName)}"></label>
          <p class="local-data-note">هذا التقييم مرتبط باسمك. تستطيع صاحبة الاستبيان والإدارة المخولة مشاهدة اسمك وإجاباتك وملاحظاتك؛ التقييم ليس مجهول الهوية.</p>
          <label class="identity-consent"><input type="checkbox" id="identityConsent"> أوافق على إرسال تقييمي باسمي وإتاحته لصاحبة الاستبيان والإدارة المخولة.</label><label class="field"><span>ملاحظاتك النصية</span><textarea id="notesText" rows="4">${escapeHtml(state.notes)}</textarea></label>
        </div>
      </div>
    </section>
  `;

  // المراجعة
  const reviewIdx = TOTAL_Q + 2;
  html += `<section class="screen" data-idx="${reviewIdx}"><div class="question-container" id="reviewContent" style="width: 100%;"></div></section>`;

   // بعد الإرسال، تشاهد المشاركة رسالة تأكيد فقط. التحليل مخصص لصاحبة الاستبيان.
   const doneIdx = TOTAL_Q + 3;
   html += `<section class="screen" data-idx="${doneIdx}">
     <div class="done-wrapper">
       <div class="done-icon">✓</div>
       <h2>تم حفظ تقييمك بنجاح</h2>
       <p>شكرًا لمشاركتك. حُفظت الإجابات على الخادم وأصبحت متاحة لصاحبة الاستبيان والإدارة المخولة.</p>
       <button class="nav-btn btn-next" style="margin:auto;" onclick="resetToHome()">العودة للرئيسية</button>
     </div></section>`;

  stage.innerHTML = html;
  attachSurveyEvents();
}

/* =====================================================================
   5) التنقل والتفاعل
   ===================================================================== */
function goTo(idx) {
  // إلغاء أي مؤقت سابق عند تغيير الصفحة يدوياً
  if (advanceTimer) clearTimeout(advanceTimer);
  
  if (idx < 0 || idx > TOTAL_Q + 3) return;
  document.querySelectorAll('.screen').forEach(el => el.classList.remove('active'));
  const target = document.querySelector(`.screen[data-idx="${idx}"]`);
  if (target) target.classList.add('active');
  
  currentScreen = idx;
  updateProgress();
  updateNav();

  if (idx === TOTAL_Q + 2) buildReview();
  // لا نعرض تقرير النتائج للمقيّمة بعد الإرسال.
}

function updateProgress() {
  let pct = 0;
  let txt = "";
  if (currentScreen === 0) { pct = 0; txt = "0 من " + TOTAL_Q; }
  else if (currentScreen > TOTAL_Q) { pct = 100; txt = "مكتمل ✓"; }
  else {
    const ansCount = Object.keys(state.answers).length;
    pct = (currentScreen / TOTAL_Q) * 100;
    txt = `${ansCount} من ${TOTAL_Q}`;
  }
  bpFill.style.width = pct + "%";
  bpText.textContent = txt;
}

function updateNav() {
  btnPrev.style.visibility = currentScreen === 0 ? "hidden" : "visible";
  btnNext.style.visibility = (currentScreen === TOTAL_Q + 3) ? "hidden" : "visible";

  btnNext.classList.remove("btn-next", "btn-submit");
  
  if (currentScreen === TOTAL_Q + 2) {
    btnNext.textContent = "إرسال التقييم";
    btnNext.classList.add("btn-submit");
    btnNext.disabled = false;
  } else if (currentScreen === 0) {
    btnNext.textContent = "ابدأ التقييم";
    btnNext.classList.add("btn-next");
    btnNext.disabled = false;
  } else if (currentScreen >= 1 && currentScreen <= TOTAL_Q) {
    btnNext.textContent = "التالي";
    btnNext.classList.add("btn-next");
    
    const q = ALL_Q[currentScreen - 1];
    if (state.answers[q.id] === undefined) {
      btnNext.disabled = true;
    } else {
      btnNext.disabled = false;
    }
  } else {
    btnNext.textContent = "التالي";
    btnNext.classList.add("btn-next");
    btnNext.disabled = false;
  }
}

btnPrev.addEventListener('click', () => {
  if (currentAppState !== 'survey') return;
  if (currentScreen === 1) {
    goTo(0);
  } else {
    goTo(currentScreen - 1);
  }
});

btnNext.addEventListener('click', () => {
  if (currentAppState !== 'survey' || btnNext.disabled) return;
  if (currentScreen === TOTAL_Q + 2) {
    submitSurvey();
    return;
  }
  goTo(currentScreen + 1);
});

function attachSurveyEvents() {
  if (!surveyClickBound) {
    stage.addEventListener('click', (e) => {
      const target = e.target.closest('.custom-segment') || e.target.closest('.custom-label');
      if (target && currentAppState === 'survey') {
        const qid = target.dataset.qid;
        const idx = Number(target.dataset.idx);
        selectAnswer(qid, idx);
      }
    });
    surveyClickBound = true;
  }

  const revInput = document.getElementById('reviewerName');
  const notesInput = document.getElementById('notesText');
  if (revInput) revInput.addEventListener('input', (e) => state.reviewerName = e.target.value);
  if (notesInput) notesInput.addEventListener('input', (e) => state.notes = e.target.value);
}

function selectAnswer(qid, idx) {
  state.answers[qid] = idx;
  const card = document.getElementById(`card-${qid}`);
  
  // 1. تحديث الواجهة (اللون الأخضر)
  if (card) {
    card.querySelectorAll('.custom-segment, .custom-label').forEach(b => b.classList.remove('selected', 'active'));
    const seg = card.querySelector(`.custom-segment[data-idx="${idx}"]`);
    const lbl = card.querySelector(`.custom-label[data-idx="${idx}"]`);
    if (seg) seg.classList.add('selected');
    if (lbl) lbl.classList.add('active');
  }

  // 2. تحديث الأزرار
  updateProgress();
  updateNav(); 

  // 3. الانتقال التلقائي الذكي
  if (advanceTimer) clearTimeout(advanceTimer);
  advanceTimer = setTimeout(() => {
    // التأكد من أننا ما زلنا في نفس السؤال ولم يقم المستخدم بالضغط على زر التالي يدوياً
    if (currentScreen >= 1 && currentScreen <= TOTAL_Q) {
      const currentQ = ALL_Q[currentScreen - 1];
      if (state.answers[currentQ.id] === idx) {
        goTo(currentScreen + 1);
      }
    }
  }, 450); // نصف ثانية تقريباً
}

/* =====================================================================
   6) المراجعة
   ===================================================================== */
function buildReview() {
  const el = document.getElementById("reviewContent");
  let html = `<div style="text-align: center; margin-bottom: 20px;"><h2 style="font-size: 1.5rem; font-weight: 900; color: var(--ink);">مراجعة الإجابات</h2><p style="font-size: 0.9rem; color: var(--muted); font-weight: 600;">راجعي إجاباتك قبل الإرسال</p></div>`;
  let currentAxis = "";
  
  ALL_Q.forEach(q => {
    const ansIdx = state.answers[q.id];
    const ansText = ansIdx !== undefined ? q.options[ansIdx] : "لم تُجب";
    if (q.axisName !== currentAxis) {
      if (currentAxis !== "") html += `<div style="height: 10px;"></div>`;
      html += `<div style="font-weight: 800; color: var(--primary); margin-bottom: 8px; font-size: 1rem; margin-top: 15px;">${escapeHtml(q.axisName)}</div>`;
      currentAxis = q.axisName;
    }
    let tone = "miss";
    if (ansIdx !== undefined) {
      const position = q.reverse ? q.options.length - 1 - ansIdx : ansIdx;
      tone = position === 0 ? 'neg' : (position === q.options.length - 1 ? 'pos' : 'mid');
    }
    html += `
      <div class="review-axis ${ansIdx !== undefined ? '' : 'incomplete'}">
        <div class="ra-head">
          <div style="width:24px; height:24px; font-size:0.7rem; background:var(--bg); color:var(--muted); border-radius:6px; display:grid; place-items:center;">${q.num}</div>
          <div class="ra-title">${escapeHtml(q.text)}</div>
          <button class="ra-edit" onclick="goTo(${q.num})">تعديل</button>
        </div>
        <div class="ra-answers"><span class="ra-chip ${tone}">${escapeHtml(ansText)}</span></div>
      </div>
    `;
  });
  el.innerHTML = html;
}

/* =====================================================================
   7) تجميع وتحليل نتائج عدة مشاركات (على هذا المتصفح للتجربة فقط)
   ===================================================================== */
function submitSurvey() {
  const missing = ALL_Q.filter(q => state.answers[q.id] === undefined);
  if (missing.length) {
    alert(`متبقٍ ${missing.length} سؤال دون إجابة.`);
    goTo(missing[0].num);
    return;
  }
  const name = (state.reviewerName || '').trim();
  if (name.length < 2) {
    alert('يرجى إدخال اسم المقيّمة في صفحة الملاحظات. في نسخة مدار سيؤخذ الاسم تلقائيًا من الحساب.');
    goTo(TOTAL_Q + 1);
    document.getElementById('reviewerName')?.focus();
    return;
  }
  try {
    saveLocalResponse(activeSurvey, activeSurveyKind, {
      id: String(Date.now()) + '-' + Math.random().toString(36).slice(2, 9),
      reviewerName: name,
      submittedAt: new Date().toISOString(),
      answers: { ...state.answers },
      notes: (state.notes || '').trim()
    });
    goTo(TOTAL_Q + 3);
  } catch (error) {
    alert('لم نتمكن من حفظ الإجابة محليًا: ' + error.message);
  }
}

function getQuestions(survey) {
  let i = 0;
  return survey.axes.flatMap((axis, axisNo) => axis.qs.map(q => ({
    ...q, id: `q${++i}`, axisName: axis.name, axisNo, num: i
  })));
}

function isScoreable(q) {
  return q.type === 'rating3' || q.type === 'rating5' ||
    (!q.type && q.options.length === 3 && q.options.every((v, i) => v === TRI[i]));
}
function ratingPercent(q, answerIndex) {
  if (!isScoreable(q) || q.options.length < 2) return null;
  let fraction = answerIndex / (q.options.length - 1);
  if (q.reverse) fraction = 1 - fraction;
  return fraction * 100; // 1/3 => 0% ، 2/3 => 50% ، 3/3 => 100%
}
function mean(values) {
  return values.length ? values.reduce((a,b) => a+b,0) / values.length : null;
}
function roundPct(x) { return x === null ? null : Math.round(x); }
function computeAggregate(survey, responses) {
  const questions = getQuestions(survey);
  const perQuestion = questions.map(q => {
    const counts = q.options.map(() => 0);
    const scores = [];
    responses.forEach(r => {
      const idx = r.answers?.[q.id];
      if (Number.isInteger(idx) && idx >= 0 && idx < q.options.length) {
        counts[idx]++;
        const score = ratingPercent(q,idx);
        if (score !== null) scores.push(score);
      }
    });
    const answered = counts.reduce((a,b)=>a+b,0);
    return { ...q, counts, answered, meanScore: mean(scores), scoreCount: scores.length };
  });
  const axes = survey.axes.map((axis,axisNo) => {
    const qs = perQuestion.filter(q=>q.axisNo===axisNo);
    // متوسّط كل المحاور يعتمد فقط على إجابات الأسئلة القابلة للقياس
    const validScores = qs.flatMap(q => {
      if (q.meanScore === null) return [];
      return Array(q.scoreCount).fill(q.meanScore);
    });
    return {name:axis.name, questions:qs, score:mean(validScores), scoredAnswers:validScores.length};
  });
  const scored = perQuestion.filter(q=>q.meanScore!==null);
  const totalWeighted = scored.reduce((s,q)=>s + q.meanScore*q.scoreCount,0);
  const totalScored = scored.reduce((s,q)=>s+q.scoreCount,0);
  const overall = totalScored ? totalWeighted / totalScored : null;
  const eligible = axes.filter(x=>x.score!==null).sort((a,b)=>b.score-a.score);
  return {
    participants: responses.length, totalScored,
    overall, axes, questions:perQuestion,
    best:eligible[0]||null, worst:eligible[eligible.length-1]||null,
    responses
  };
}
function getRatingColor(s) { return s >= 85 ? 'var(--ex)' : s >= 70 ? 'var(--gd)' : 'var(--im)'; }
function getRatingLabel(s) { return s >= 85 ? 'ممتاز' : s >= 70 ? 'جيد' : 'يحتاج إلى تحسين'; }
function formatPct(s) { return s === null ? 'غير متاح' : roundPct(s) + '%'; }

function openLocalReport(kind) {
  const survey = kind === 'applied' ? SURVEY_APPLIED : kind === 'workshop' ? SURVEY_WORKSHOP : customSurvey;
  const responses = readLocalResponses(survey,kind);
  displayDashboard(survey, responses, false);
}

// معاينة اصطناعية فقط، لا تحفظ أي إجابات ولا تمثل أشخاصًا حقيقيين.
function openPreviewReport(kind) {
  const survey = kind === 'workshop' ? SURVEY_WORKSHOP : SURVEY_APPLIED;
  const questions = getQuestions(survey);
  const responses = Array.from({length:24},(_,n) => {
    const answers = {};
    questions.forEach(q => {
      const x = (n * 7 + q.num * 3 + ((n+2) * q.num)%9) % 17;
      answers[q.id] = x < 4 ? 0 : x < 8 ? 1 : 2;
    });
    return {
      id:'sample-'+(n+1), reviewerName:'مشاركة توضيحية '+String(n+1).padStart(2,'0'),
      submittedAt:new Date(Date.UTC(2026,9,1+n%12,9)).toISOString(),
      answers, notes:n===0?'مثال توضيحي للملاحظات، وليس رأيًا حقيقيًا.':''
    };
  });
  displayDashboard(survey, responses, true);
}

function displayDashboard(survey, responses, demo) {
  currentAppState = 'analysis';
  navBar.style.display = 'none';
  progressContainer.style.visibility = 'hidden';
  btnReset.style.display = 'block';
  renderAggregateReport(survey, computeAggregate(survey, responses), demo);
}

const chartPalette = ['#de6474','#edba57','#0d927b','#458bc2','#866abd','#c18f59'];
function chartColor(options, index) {
  if (options.length === 5 && options.every((v,i)=>String(v)===String(i+1))) return ['#ef4444','#f59e0b','#facc15','#84cc16','#22c55e'][index];
  const name = String(options[index] ?? '').trim();
  if (name === 'لا' || name === '1' || name === 'غير موافق') return chartPalette[0];
  if (name === 'نوعاً ما' || name === 'نوعًا ما' || name === '2' || name === 'محايد') return chartPalette[1];
  if (name === 'نعم' || name === '3' || name === 'موافق') return chartPalette[2];
  return chartPalette[index % chartPalette.length];
}
function legibleSegmentText(options,index) {
  const c = chartColor(options,index);
  return c === chartPalette[1] ? 'some' : '';
}
function questionRank(q) {
  // لا تظهر الأسئلة التي لم تتلقّ استجابات أو ليست قابلة للتقييم الرقمي.
  return q.meanScore === null || q.answered === 0 ? null : q.meanScore;
}
function compactQuestionLabel(q) {
  return `<div class="question-label"><span class="q-index">${q.num}</span>
    <span class="q-name" title="${escapeHtml(q.text)}">${escapeHtml(q.text)}</span>
    ${q.reverse?'<span class="q-reverse" title="يُعكس ترميز هذا السؤال عند حساب مستوى الأداء">عكسي</span>':''}</div>`;
}
function compactBar(q) {
  if (!q.answered) return '<div class="stacked-track"><span class="chart-no-data">لا توجد إجابات</span></div>';
  const segments = q.counts.map((count,i)=>{
    const pct=count/q.answered*100;
    if (count===0) return '';
    const info = `${q.text} — ${q.options[i]}: ${count} مشاركة (${pct.toFixed(1)}%)`;
    const showPct = pct >= 12;
    return `<span class="stack-segment ${legibleSegmentText(q.options,i)}" tabindex="0" role="img"
      aria-label="${escapeHtml(info)}" title="${escapeHtml(info)}"
      style="width:${pct.toFixed(4)}%;background:${chartColor(q.options,i)}">${showPct?Math.round(pct)+'%':''}</span>`;
  }).join('');
  return `<div class="stacked-track" aria-label="توزيع إجابات السؤال ${q.num}">${segments}</div>`;
}
function insightList(questions, highest) {
  const eligible = questions.filter(q=>questionRank(q)!==null);
  eligible.sort((a,b)=>highest?(b.meanScore-a.meanScore||a.num-b.num):(a.meanScore-b.meanScore||a.num-b.num));
  if (!eligible.length) return '<li>لا توجد استجابات رقمية كافية لعرض النتائج.</li>';
  return eligible.slice(0,3).map(q=>`<li>${escapeHtml(q.text)} <small>(${formatPct(q.meanScore)})</small></li>`).join('');
}
function buildAxisOverview(data) {
  const cards = data.axes.map((ax,i)=>{
    const present=ax.score!==null && Number.isFinite(ax.score);
    const score=present?Math.max(0,Math.min(100,ax.score)):0;
    const grade=present?getRatingLabel(score):'لا توجد بيانات';
    const col=present?getRatingColor(score):'#9ca3af';
    return `<div class="axis-mini" title="${escapeHtml(ax.name)} — ${present?formatPct(score):'لا توجد بيانات'} — ${ax.scoredAnswers||0} إجابة رقمية">
      <div class="axis-mini-header"><span class="axis-mini-name">${i+1}. ${escapeHtml(ax.name)}</span><span class="axis-mini-score" style="color:${col}">${formatPct(ax.score)}</span></div>
      <div class="axis-mini-track" role="progressbar" aria-label="${escapeHtml(ax.name)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(score)}"><div class="axis-mini-fill" style="background:${col};width:${score.toFixed(2)}%"></div></div>
      <div class="axis-mini-foot"><span>${present?grade:'—'}</span><b>${ax.scoredAnswers||0} إجابة</b></div>
    </div>`;
  }).join('');
  return `<section class="axes-panel" aria-label="تحليل محاور الاستبيان">
    <div class="axes-topline"><h2>تحليل محاور الاستبيان</h2><span class="axis-description">متوسط الأداء في كل محور · بعد تصحيح الأسئلة العكسية</span></div>
    <div class="axes-grid">${cards}</div></section>`;
}

function renderAggregateReport(survey, data, demo=false) {
  const scoredAxes = data.axes.filter(a=>a.score!==null).sort((a,b)=>b.score-a.score);
  const best = scoredAxes[0] || null, worst = scoredAxes[scoredAxes.length-1] || null;
  let html = `<section class="screen active"><div class="analysis-container"><div class="compact-dashboard">
    ${schoolHeaderHTML('تقرير تحليل نتائج الاستبيان', survey.title + ' · ' + survey.teacher + (survey.lesson ? ' · '+survey.lesson : ''), demo)}
    <div class="dashboard-head">
      <div class="dashboard-brand"><div class="dashboard-emblem">مدار</div><div>
      <h1>لوحة تحليل نتائج الاستبيان</h1>
      <div class="subtitle">${escapeHtml(survey.title)} · ${escapeHtml(survey.teacher)} · ${escapeHtml(survey.lesson||'')}</div>
      </div></div>
      <div class="report-actions">
        <button type="button" onclick="printReport()" title="اختاري حفظ بصيغة PDF من نافذة الطباعة">🖨 طباعة / حفظ تقرير PDF</button>
        <button type="button" onclick="resetToHome()">العودة للرئيسية</button>
      </div>
    </div>
    ${demo?'<div class="preview-flag">هذه معاينة توضيحية فقط — جميع الأرقام والأسماء افتراضية</div>':''}
    ${!demo?'<div class="compact-footnote">نتائج محفوظة على الخادم. هذه البيانات متاحة لصاحبة الاستبيان والإدارة المخولة فقط.</div>':''}`;
  if (!data.participants) {
    html += `<div class="demo-callout">لا توجد مشاركات لهذا الاستبيان بعد. شاركي رابطه بعد نشره.</div>`;
  } else {
    html += `<div class="compact-stats">
      <div class="compact-stat"><div class="k">${data.participants}</div><div class="lab">عدد المشاركات</div></div>
      <div class="compact-stat"><div class="k">${formatPct(data.overall)}</div><div class="lab">متوسط التقييم الرقمي</div></div>
      <div class="compact-stat"><div class="k small" title="${best?escapeHtml(best.name):''}">${best?escapeHtml(best.name):'—'}</div><div class="lab">المحور الأعلى ${best?'· '+formatPct(best.score):''}</div></div>
      <div class="compact-stat"><div class="k small" title="${worst?escapeHtml(worst.name):''}">${worst?escapeHtml(worst.name):'—'}</div><div class="lab">المحور الأقل ${worst?'· '+formatPct(worst.score):''}</div></div>
    </div>
    ${buildAxisOverview(data)}
    <div class="compact-sheet" id="chart-one">
      <div class="sheet-heading"><div class="sheet-title">توزيع الإجابات لجميع الأسئلة</div>
      <div class="sheet-meta">رسم أفقي مكدّس موحّد · ${data.questions.length} سؤالًا · النسب من الإجابات الفعلية لكل سؤال</div></div>
      <div class="sheet-legend" data-original-legend>
        <span class="legend-item"><i style="background:${chartPalette[0]}"></i>لا / 1</span>
        <span class="legend-item"><i style="background:${chartPalette[1]}"></i>نوعًا ما / 2</span>
        <span class="legend-item"><i style="background:${chartPalette[2]}"></i>نعم / 3</span>
        <span style="color:#83919b;font-size:.79rem">مرري المؤشر أو اضغطي مطولًا على جزء الشريط لمعرفة العدد والنسبة</span>
      </div>`;
    data.axes.forEach((ax,ai)=>{
      html += `<div class="chart-axis">
         <div class="chart-axis-title"><span class="axis-num">${ai+1}</span>${escapeHtml(ax.name)}</div>`;
      ax.questions.forEach(q=>{
        html += `<div class="chart-row">${compactQuestionLabel(q)}${compactBar(q)}
          <div class="score-pill" title="متوسط الأداء المصحح لهذا السؤال">${formatPct(q.meanScore)}</div></div>`;
      });
      html += '</div>';
    });
    html += `<div class="chart-caption"><span>الألوان تعرض الإجابات الأصلية كما هي، بينما درجات الأداء تراعي الأسئلة ذات الصياغة العكسية.</span><span>العمود الأخير: مؤشر الأداء</span></div></div>
    <div class="summary-context">${best&&worst ? `تحليل المحاور: الأعلى «${escapeHtml(best.name)}» (${formatPct(best.score)})، والأقل «${escapeHtml(worst.name)}» (${formatPct(worst.score)}). ${worst.score<70?'يُستحسن مراجعة الأسئلة منخفضة التقييم في المحور الأقل.':'تُراجع المؤشرات التفصيلية لتحديد فرص التطوير.'}` : 'لم تتوفر إجابات رقمية كافية لاستخراج مقارنة بين المحاور.'}</div>
    <div class="compact-bottom">
      <div class="insight-panel"><h3>✓ أعلى 3 مؤشرات</h3><ul>${insightList(data.questions,true)}</ul></div>
      <div class="insight-panel"><h3>↗ أبرز 3 فرص للتحسين</h3><ul>${insightList(data.questions,false)}</ul></div>
    </div>
    <details class="detail-drawer"><summary>ملاحظات المشاركات (${data.responses.filter(x=>x.notes&&x.notes.trim()).length})</summary><div class="detail-body">
      ${data.responses.filter(x=>x.notes&&x.notes.trim()).map(r=>`<div class="note-row"><b>${escapeHtml(r.reviewerName)}</b><p>${escapeHtml(r.notes)}</p></div>`).join('')||'<p>لا توجد ملاحظات.</p>'}
    </div></details>
    <details class="detail-drawer"><summary>عرض أسماء المشاركات وإجاباتهن التفصيلية (${data.participants})</summary><div class="detail-body">`;
    data.responses.forEach((r,i)=>{
      const dt=new Date(r.submittedAt);
      html += `<details class="reviewer-details"><summary>${i+1}. ${escapeHtml(r.reviewerName)} <span>${Number.isNaN(dt.getTime())?'':escapeHtml(dt.toLocaleString('ar-SA'))}</span></summary><div>`;
      data.questions.forEach(q=>{
        const ix=r.answers?.[q.id];
        html+=`<div class="review-answer-row"><span>${escapeHtml(q.text)}</span><b>${Number.isInteger(ix)&&ix>=0&&ix<q.options.length?escapeHtml(q.options[ix]):'لم تُجب'}</b></div>`;
      });
      html+='</div></details>';
    });
    html+='</div></details>';
    html += `<div class="compact-footnote">${demo?'تنبيه: هذه الأرقام أنشئت للتوضيح ولا تمثل تقييمات حقيقية.':'بيانات شخصية مرتبطة بحسابات المشاركات؛ استخدمي التقرير وفق صلاحياتك.'} عند الطباعة يُستخدم مقاس A3 ويُقسّم المحتوى الطويل إلى صفحات دون حذف الأسئلة.</div>`;
  }
  html += `<footer class="report-print-footer">
      <span>${escapeHtml(SCHOOL_NAME)} · نظام استبيانات مدار</span>
      <span>${demo ? 'بيانات توضيحية افتراضية – ليست تقرير تقييم حقيقي' : 'تقرير نتائج الاستبيان'}</span>
    </footer>`;
  html+='</div></div></section>';
  stage.innerHTML=html;
}

function printReport() {
  if (currentAppState !== 'analysis' || !stage.querySelector('.official-letterhead')) return;
  // تنتج نافذة الطباعة ملف PDF عند اختيار «حفظ بصيغة PDF».
  window.print();
}

/* =====================================================================
   8) العودة للبداية
   ===================================================================== */
function resetToHome() {
  if (advanceTimer) clearTimeout(advanceTimer);
  if (currentAppState === 'survey' || currentAppState === 'builder') {
    if (!confirm("هل أنت متأكد من العودة للصفحة الرئيسية؟ سيتم فقدان أي بيانات غير محفوظة.")) return;
  }
  currentAppState = 'home';
  buildHomeScreen();
}

